'use strict';
window.FolioTranslation=(()=>{
 let options={source:'en',target:'zh-CN',auto:false,mouse:'none',shortcut:{code:'KeyT',key:'T',alt:true,ctrl:false,shift:false,meta:false}};
 let selected=null,requestId=0,connection,customDictionary=null;
 const buckets=new Map();
 const ready=database().then(async db=>{connection=db;const saved=await setting('get');if(saved)options={...options,...saved};customDictionary=await dictionary('get','custom')||null;sync();}).catch(()=>{sync();message('Translation settings cannot be saved because local storage is unavailable.');});
 function setting(method){return new Promise((resolve,reject)=>{const tx=connection.transaction('settings',method==='get'?'readonly':'readwrite');const request=method==='get'?tx.objectStore('settings').get('translation'):tx.objectStore('settings').put({id:'translation',...options});tx.oncomplete=()=>resolve(request.result);tx.onerror=()=>reject(tx.error);});}
 function dictionary(method,value){return new Promise((resolve,reject)=>{const tx=connection.transaction('dictionaries',method==='get'?'readonly':'readwrite');const request=tx.objectStore('dictionaries')[method](value);tx.oncomplete=()=>resolve(request.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
 function shortcutLabel(){const s=options.shortcut;return [s.ctrl?'Ctrl':null,s.alt?'Alt':null,s.shift?'Shift':null,s.meta?'Meta':null,s.key].filter(Boolean).join(' + ');}
 function dictionaryStatus(){const status=$('dictionary-status'),remove=$('dictionary-remove');if(customDictionary){status.textContent=`${customDictionary.name} · ${Number(customDictionary.count).toLocaleString()} imported entries · Used before ECDICT`;remove.hidden=false;}else{status.textContent='Local ECDICT · 768,739 entries · Works offline';remove.hidden=true;}}
 function sync(){$('translation-source').value=options.source;$('translation-target').value=options.target;$('translation-shortcut').value=shortcutLabel();$('translation-mouse').value=options.mouse;$('translation-auto').setAttribute('aria-checked',String(options.auto));$('translation-auto').querySelector('span').textContent=options.auto?'On':'Off';dictionaryStatus();}
 async function save(){await ready;if(!connection){message('Could not save translation settings because local storage is unavailable.');return;}await setting('put').catch(()=>message('Could not save translation settings. Please try again.'));}
 function close(){requestId++;$('translation-result').hidden=true;}
 function remember(doc){const selection=doc.getSelection();if(!selection||selection.isCollapsed||!selection.rangeCount)return;const word=selection.toString().trim();if(!word||word.length>100)return;const range=selection.getRangeAt(0).cloneRange();selected={word,doc,range};}
 function toggle(doc){if(!$('translation-result').hidden){close();return;}translate(doc);}
 function sideButton(e){if(options.mouse==='none'||e.button!==Number(options.mouse)||$('reader').hidden)return;e.preventDefault();e.stopPropagation();if(e.type==='pointerup')toggle(e.target?.ownerDocument);}
 function wireMouse(doc){for(const event of ['pointerdown','pointerup','mousedown','mouseup','auxclick'])doc.addEventListener(event,sideButton,{capture:true});}
 function attach(doc){doc.addEventListener('selectionchange',()=>remember(doc));doc.addEventListener('dblclick',()=>{remember(doc);if(options.auto)translate(doc);});doc.addEventListener('pointerdown',e=>{if(e.button!==0)return;close();selected=null;});wireMouse(doc);}
 function position(){if(!selected)return;const box=selected.range.getBoundingClientRect();const frame=selected.doc.defaultView.frameElement;const offset=frame?.getBoundingClientRect()||{left:0,top:0};const popup=$('translation-result');const left=offset.left+box.left;const bottom=offset.top+box.bottom;popup.style.left=Math.max(12,Math.min(innerWidth-popup.offsetWidth-12,left))+'px';popup.style.top=Math.max(8,Math.min(innerHeight-popup.offsetHeight-12,bottom+10))+'px';}
 function hashWord(word){let hash=2166136261;for(const c of word)hash=Math.imul(hash^c.charCodeAt(0),16777619)>>>0;return (hash&255).toString(16).padStart(2,'0');}
 function loadBucket(key){return new Promise((resolve,reject)=>{globalThis.__FolioDictionaryBuckets??=Object.create(null);const script=document.createElement('script');script.src='dictionary/'+key+'.js';script.async=true;script.onload=()=>{const bucket=globalThis.__FolioDictionaryBuckets[key];delete globalThis.__FolioDictionaryBuckets[key];script.remove();bucket?resolve(bucket):reject(new Error('The local dictionary file is invalid.'));};script.onerror=()=>{script.remove();reject(new Error('The local dictionary is unavailable. Open Folio from its complete folder and try again.'));};document.head.append(script);});}
 async function entry(word){if(customDictionary&&Object.hasOwn(customDictionary.entries,word))return customDictionary.entries[word];const key=hashWord(word);if(!buckets.has(key)){const promise=loadBucket(key).catch(error=>{buckets.delete(key);throw error;});buckets.set(key,promise);}const bucket=await buckets.get(key);return Object.hasOwn(bucket,word)?bucket[word]:null;}
 function dictionaryData(value){if(Array.isArray(value)){const data=value.slice(0,4).map(item=>item==null?'':String(item));while(data.length<4)data.push('');if(!data[3])data[3]=data[0];return data;}if(typeof value==='string')return[value,'','',value];if(!value||typeof value!=='object')return null;const fallback=value.definition??value.definitions??value.meaning??value.translation??'';const zh=value['zh-CN']??value.zh??value.chinese??fallback;const en=value.en??value.english??fallback??zh;return[String(zh||''),'','',String(en||zh||'')];}
 function dictionaryRows(text,delimiter){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"')quoted=true;else if(c===delimiter){row.push(cell);cell='';}else if(c==='\n'){row.push(cell);rows.push(row);row=[];cell='';}else if(c!=='\r')cell+=c;}row.push(cell);if(row.some(value=>value.trim()))rows.push(row);return rows;}
 async function dictionaryText(file){const data=await file.arrayBuffer(),bytes=new Uint8Array(data);if(bytes[0]===0xff&&bytes[1]===0xfe)return new TextDecoder('utf-16le').decode(data);if(bytes[0]===0xfe&&bytes[1]===0xff)return new TextDecoder('utf-16be').decode(data);try{return new TextDecoder('utf-8',{fatal:true}).decode(data);}catch{try{return new TextDecoder('gb18030',{fatal:true}).decode(data);}catch{throw new Error('The text encoding is not supported. Use UTF-8, UTF-16 or GB18030.');}}}
 function parseDictionary(file,text){const entries={};const add=(rawWord,value)=>{const word=String(rawWord||'').trim().toLowerCase().replace(/’/g,"'");if(!/^[a-z][a-z' -]*$/i.test(word))return;const data=dictionaryData(value);if(data&&(data[0]||data[3]))entries[word]=data;};if(/\.json$/i.test(file.name)){const parsed=JSON.parse(text.replace(/^\uFEFF/,''));if(Array.isArray(parsed)){for(const item of parsed){if(Array.isArray(item))add(item[0],item.length===2?item[1]:item.slice(1));else if(item&&typeof item==='object')add(item.word??item.term??item.headword,item);}}else if(parsed&&typeof parsed==='object'){for(const [word,value] of Object.entries(parsed))add(word,value);}else throw new Error('JSON must contain an object or an array of entries.');}else{const delimiter=/\.csv$/i.test(file.name)?',':'\t',rows=dictionaryRows(text.replace(/^\uFEFF/,''),delimiter);if(!rows.length)throw new Error('The dictionary file is empty.');const header=rows[0].map(value=>value.trim().toLowerCase()),hasHeader=['word','term','headword'].some(value=>header.includes(value));let wordIndex=0,zhIndex=1,enIndex=2;if(hasHeader){wordIndex=header.findIndex(value=>['word','term','headword'].includes(value));zhIndex=header.findIndex(value=>['zh','zh-cn','chinese','translation','definition'].includes(value));enIndex=header.findIndex(value=>['en','english'].includes(value));}for(const row of rows.slice(hasHeader?1:0)){const common=row[zhIndex>=0?zhIndex:1]||'';add(row[wordIndex],{zh:common,en:enIndex>=0?row[enIndex]:common});}}const count=Object.keys(entries).length;if(!count)throw new Error('No valid English word entries were found.');return entries;}
 async function importDictionary(file){if(!file)return;try{if(!/\.(json|csv|tsv|txt)$/i.test(file.name))throw new Error('Choose a JSON, CSV, TSV or TXT dictionary.');if(file.size>100*1024*1024)throw new Error('The dictionary must be 100 MB or smaller.');message(`Importing “${file.name}”…`);const entries=parseDictionary(file,await dictionaryText(file)),record={id:'custom',name:file.name,count:Object.keys(entries).length,entries};await ready;customDictionary=record;if(connection)await dictionary('put',record);dictionaryStatus();buckets.clear();message(`Imported ${record.count.toLocaleString()} dictionary entries.`);}catch(error){message(`Could not import the dictionary: ${error.message}`);}finally{$('dictionary-input').value='';}}
 async function removeDictionary(){await ready;try{if(connection)await dictionary('delete','custom');customDictionary=null;dictionaryStatus();message('Imported dictionary removed. ECDICT is active.');}catch(error){message(`Could not remove the dictionary: ${error.message}`);}}
 async function lookup(word){let found=await entry(word);if(found)return {word,data:found};const stems=new Set();if(word.endsWith("'s"))stems.add(word.slice(0,-2));if(word.endsWith('ies'))stems.add(word.slice(0,-3)+'y');if(word.endsWith('s'))stems.add(word.slice(0,-1));if(word.endsWith('es'))stems.add(word.slice(0,-2));for(const suffix of ['ing','ed'])if(word.endsWith(suffix)){const stem=word.slice(0,-suffix.length);stems.add(stem);stems.add(stem+'e');if(stem.at(-1)===stem.at(-2))stems.add(stem.slice(0,-1));}for(const stem of stems){found=await entry(stem);if(found)return {word:stem,data:found};}return null;}
 function definitions(result){const area=$('translation-definitions');area.replaceChildren();const text=options.target==='en'?result.data[3]:result.data[0];if(!text){area.textContent='No definition is available in this language.';return;}for(const line of text.split('\n').filter(Boolean)){const p=document.createElement('p');const match=line.match(/^\s*((?:(?:n|v|vt|vi|adj|a|adv|ad|pron|prep|conj|interj|int|num|art|aux|abbr|pl)\.?\s*(?:&\s*)?)+)\.\s*(.+)$/i);if(match){const pos=document.createElement('span');pos.className='translation-pos';pos.textContent=match[1]+'.';p.append(pos,document.createTextNode(match[2]));}else p.textContent=line;area.append(p);}}
 async function translate(doc){await ready;if(busy||$('reader').hidden)return;if(doc)remember(doc);if(!selected||!selected.doc.defaultView||!selected.range.startContainer.isConnected){message('Double-click a word first.');return;}const word=selected.word.replace(/^[^a-zA-Z]+|[^a-zA-Z]+$/g,'').toLowerCase().replace(/’/g,"'");const token=++requestId;$('translated-word').textContent=selected.word;$('translation-result').hidden=false;$('translation-definitions').textContent='Looking up…';position();if(!word||!/^[a-z][a-z' -]*$/i.test(word)){$('translation-definitions').textContent='Select an English word.';position();return;}try{const result=await lookup(word);if(token!==requestId)return;if(result)definitions(result);else $('translation-definitions').textContent='This word is not in the local dictionary.';position();}catch(error){if(token===requestId){$('translation-definitions').textContent=error.message;position();}}}
 function handleKey(e){if(e.target?.id==='translation-shortcut')return false;if(e.key==='Escape'&&!$('translation-result').hidden){e.preventDefault();close();return true;}const s=options.shortcut;if(e.code===s.code&&e.altKey===s.alt&&e.ctrlKey===s.ctrl&&e.shiftKey===s.shift&&e.metaKey===s.meta){if(e.target?.closest?.('input,textarea,select'))return false;e.preventDefault();e.stopPropagation();if(!e.repeat)toggle(e.target?.ownerDocument);return true;}return false;}
 $('translation-toggle').onclick=()=>{const panel=$('translation-settings');panel.hidden=!panel.hidden;$('settings').hidden=true;$('toc').hidden=true;close();};
 $('translation-target').onchange=e=>{options.target=e.target.value;save();close();};
 $('dictionary-import').onclick=()=>$('dictionary-input').click();$('dictionary-input').onchange=e=>importDictionary(e.target.files[0]);$('dictionary-remove').onclick=removeDictionary;
 $('translation-auto').onclick=()=>{options.auto=!options.auto;sync();save();};
 $('translation-mouse').onchange=e=>{options.mouse=e.target.value;save();};
 $('translation-shortcut').onkeydown=e=>{e.preventDefault();e.stopPropagation();if(['Control','Alt','Shift','Meta'].includes(e.key))return;if(e.key==='Escape'){$('translation-shortcut').blur();return;}if(!(e.altKey||e.ctrlKey||e.metaKey)||!e.code||['Tab','Enter','Space'].includes(e.code)){message('Use Alt, Ctrl or Meta with a letter, number or punctuation key.');return;}const names={Comma:',',Period:'.',Slash:'/',Semicolon:';',Quote:"'",BracketLeft:'[',BracketRight:']',Backslash:'\\',Minus:'-',Equal:'=',Backquote:'`'};options.shortcut={code:e.code,key:names[e.code]||e.code.replace(/^Key|^Digit/,''),alt:e.altKey,ctrl:e.ctrlKey,shift:e.shiftKey,meta:e.metaKey};sync();save();$('translation-shortcut').blur();};
 $('translation-close').onclick=close;window.addEventListener('resize',close);document.addEventListener('pointerdown',e=>{if(!e.target.closest('#translation-result'))close();});
 wireMouse(document);
 return {attach,handleKey,close,lookup,importDictionary};
})();

